<?php require __DIR__.'/../includes/bootstrap.php';require_admin();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$slug=trim($_POST['slug']??'');$image=trim($_POST['image']??'');$sort=(int)($_POST['sort_order']??0);if($name&&$slug){if($id)db()->prepare('UPDATE categories SET name=?,slug=?,image=?,sort_order=? WHERE id=?')->execute([$name,$slug,$image,$sort,$id]);else db()->prepare('INSERT INTO categories(name,slug,image,sort_order) VALUES(?,?,?,?)')->execute([$name,$slug,$image,$sort]);$msg='تم حفظ القسم.';}}$cats=db()->query('SELECT * FROM categories ORDER BY sort_order,id')->fetchAll();?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>الأقسام</title><link rel="stylesheet" href="../assets/css/store.css"></head><body><main class="inner"><a href="index.php">← لوحة التحكم</a><h1>إدارة الأقسام</h1><?php if($msg):?><p class="notice"><?=h($msg)?></p><?php endif?><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><label>اسم القسم<input name="name" required></label><label>الرابط اللاتيني (slug)<input name="slug" required></label><label>رابط الصورة<input name="image"></label><label>ترتيب العرض<input type="number" name="sort_order" value="0"></label><button class="gold">إضافة قسم</button></form><div class="table-wrap"><table><tr><th>القسم</th><th>Slug</th><th>الترتيب</th></tr><?php foreach($cats as $c):?><tr><td><?=h($c['name'])?></td><td><?=h($c['slug'])?></td><td><?=$c['sort_order']?></td></tr><?php endforeach?></table></div></main></body></html>